import{_ as s,o as t,c as n,a4 as e}from"./chunks/framework.BRzJ4ijD.js";const d=JSON.parse('{"title":"2. 抽象层级: 从晶体管到 AI 模型的十层金字塔","description":"","frontmatter":{},"headers":[],"relativePath":"prologue/abstraction-layers.md","filePath":"prologue/abstraction-layers.md","lastUpdated":1788475713000}'),l={name:"prologue/abstraction-layers.md"};function i(r,a,o,p,c,h){return t(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="_2-抽象层级-从晶体管到-ai-模型的十层金字塔" tabindex="-1">2. 抽象层级: 从晶体管到 AI 模型的十层金字塔 <a class="header-anchor" href="#_2-抽象层级-从晶体管到-ai-模型的十层金字塔" aria-label="Permalink to &quot;2. 抽象层级: 从晶体管到 AI 模型的十层金字塔&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>计算机科学的本质 = <strong>分层抽象</strong>: 每一层<strong>为上层提供契约</strong> (一组语法 + 语义 + 不变式), 上层<strong>不知道也不需要知道</strong>下层如何实现. <strong>但抽象会泄漏</strong> — 当下层契约被打破时, 上层必须有人理解并修复.</p><p>这条&quot;十层金字塔&quot;从前一天最熟悉的程序语言脚本一路下钻到晶体管电压, 再上钻到 AI 模型. 一共 10 层, 每层一句话:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────┐</span></span>
<span class="line"><span>│ 10. AI 模型 / 智能体层 (Agent)         │   GPT / Claude / Agent</span></span>
<span class="line"><span>│  9. 应用与框架层                       │   web / db / 分布式 / 编程框架</span></span>
<span class="line"><span>│  8. 高级语言运行时层                   │   Java JVM / Python / V8</span></span>
<span class="line"><span>│  7. 系统调用接口层                     │   POSIX / Win32</span></span>
<span class="line"><span>│  6. 操作系统内核层                     │   Linux / NT</span></span>
<span class="line"><span>│  5. 指令集架构 (ISA) 层               │   x86-64 / ARM / RISC-V</span></span>
<span class="line"><span>│  4. 微架构 (microarch) 层              │   流水线 / 超标量 / cache / OoO</span></span>
<span class="line"><span>│  3. 数字逻辑层                         │   RTL / 门 / 触发器 / FSM</span></span>
<span class="line"><span>│  2. 模拟电路层                         │   放大器 / ADC / DAC</span></span>
<span class="line"><span>│  1. 半导体器件物理层                   │   MOSFET / 晶体管 / PN 结</span></span>
<span class="line"><span>└──────────────────────────────────────┘</span></span></code></pre></div><p>读完应能: 任意给一份技术资料能立刻说出它在哪一层 / 它依赖下层哪契约 / 它向上提供什么. 看到现象 (&quot;Redis 抖动&quot;或 &quot;Hyper-threading 引起 30% slowdown&quot;) 能沿层级定位泄漏源.</p><hr><h2 id="一、为什么抽象分层" tabindex="-1">一、为什么抽象分层 <a class="header-anchor" href="#一、为什么抽象分层" aria-label="Permalink to &quot;一、为什么抽象分层&quot;">​</a></h2><h3 id="_1-1-复杂度-vs-单脑容量" tabindex="-1">1.1 复杂度 vs 单脑容量 <a class="header-anchor" href="#_1-1-复杂度-vs-单脑容量" aria-label="Permalink to &quot;1.1 复杂度 vs 单脑容量&quot;">​</a></h3><ul><li>现代数据中心有 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>∼</mo><msup><mn>10</mn><mn>18</mn></msup></mrow><annotation encoding="application/x-tex">\\sim 10^{18}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.3669em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">18</span></span></span></span></span></span></span></span></span></span></span></span> 晶体管, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>∼</mo><msup><mn>10</mn><mn>9</mn></msup></mrow><annotation encoding="application/x-tex">\\sim 10^9</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.3669em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight">9</span></span></span></span></span></span></span></span></span></span></span> 行代码, 个人脑容量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>∼</mo><msup><mn>10</mn><mn>11</mn></msup></mrow><annotation encoding="application/x-tex">\\sim 10^{11}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.3669em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">11</span></span></span></span></span></span></span></span></span></span></span></span> neurons. 显然不可能&quot;自上而下&quot; 一气讲清.</li><li>抽象分层 = <strong>把능力分工</strong>: 一层专家可以专心设计下一层 + 履行契约, 上层专家可以<strong>假定契约不变</strong>.</li></ul><h3 id="_1-2-每层的契约" tabindex="-1">1.2 每层的契约 <a class="header-anchor" href="#_1-2-每层的契约" aria-label="Permalink to &quot;1.2 每层的契约&quot;">​</a></h3><ul><li><strong>语法</strong>: 什么样的输入合法.</li><li><strong>语义</strong>: 输入对应什么输出 / 系统行为.</li><li><strong>不变式</strong>: 上层可以依靠的&quot;始终为真&quot;的保证 (e.g. &quot;malloc 返回 non-NULL 不意味分配成功, 还要 free&quot;; &quot;TCP 是 reliable&quot; 不变式 vs 链路层&quot;按位丢失&quot; 等等).</li></ul><h3 id="_1-3-抽象会泄漏" tabindex="-1">1.3 抽象会泄漏 <a class="header-anchor" href="#_1-3-抽象会泄漏" aria-label="Permalink to &quot;1.3 抽象会泄漏&quot;">​</a></h3><blockquote><p>&quot;All non-trivial abstractions, to some degree, are leaky.&quot; —— Joel Spolsky, 2002.</p></blockquote><p>抽象整层错误不存, 至少六个典型泄漏手段:</p><ul><li><strong>性能泄漏</strong>: 上层假设&quot;免费&quot;, 实际 cache miss / page fault / GC pause.</li><li><strong>正确性泄漏</strong>: 上层定义 OK, 下层在并发 / 故障下会违反契约 (e.g. fsync 在某些 fs / drive 上不保证 crash safe).</li><li><strong>资源泄漏</strong>: 上层 closure / lambda 引用底层 file descriptor 不释放; OOM.</li><li><strong>延迟泄漏</strong>: 上层 RPC, 下层跨网 RTT 50ms, 上层调 1000 次 = 50s.</li><li><strong>资源粒度泄漏</strong>: 上层&quot;加 1 字节&quot; 在下层是&quot;加 1 page&quot; (4KB).</li><li><strong>失败模型泄漏</strong>: 物理断电 → 网络 quiet → 上层 app 假死.</li></ul><p>→ <strong>本书每一部分都是某一层专家视角</strong>, 第十三部分元抽象专门谈同级跨层共同点.</p><hr><h2 id="二、底层向上-第-1-4-层" tabindex="-1">二、底层向上: 第 1-4 层 <a class="header-anchor" href="#二、底层向上-第-1-4-层" aria-label="Permalink to &quot;二、底层向上: 第 1-4 层&quot;">​</a></h2><h3 id="_2-1-第-1-层-半导体器件物理" tabindex="-1">2.1 第 1 层: 半导体器件物理 <a class="header-anchor" href="#_2-1-第-1-层-半导体器件物理" aria-label="Permalink to &quot;2.1 第 1 层: 半导体器件物理&quot;">​</a></h3><p><strong>契约</strong>: 把外部电压 / 电流转换为可预测的&quot;开关&quot;行为.</p><ul><li>MOSFET (Metal-Oxide-Semiconductor Field-Effect Transistor): 三端 Gate/Source/Drain, Gate 电压控 Source↔Drain 通道.</li><li>工艺节点 (5nm / 3nm / 2nm) 是 marketing 词; 真晶体管密度与 pitch 跟名字关系不严格对应.</li><li>关键变数: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>V</mi><mrow><mi>t</mi><mi>h</mi></mrow></msub></mrow><annotation encoding="application/x-tex">V_{th}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">h</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> (阈值), <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>I</mi><mrow><mi>o</mi><mi>n</mi></mrow></msub><mi mathvariant="normal">/</mi><msub><mi>I</mi><mrow><mi>o</mi><mi>f</mi><mi>f</mi></mrow></msub></mrow><annotation encoding="application/x-tex">I_{on}/I_{off}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">/</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 比, 漏流 (static power), 短沟道效应, 量子隧穿.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>2005 后 Dennard scaling 退场: 同面积功耗不再随节点下降 → 主频不能无限升 → 多核化 → 2010+ 加速器化. 这是后面所有 XPU 故事的根.</p></div><h3 id="_2-2-第-2-层-模拟电路" tabindex="-1">2.2 第 2 层: 模拟电路 <a class="header-anchor" href="#_2-2-第-2-层-模拟电路" aria-label="Permalink to &quot;2.2 第 2 层: 模拟电路&quot;">​</a></h3><p><strong>契约</strong>: 把 MOSFET、电阻、电容组成放大器、ADC/DAC、PLL、SRAM cell.</p><ul><li>SRAM 单元 = 6T, 6 个晶体管组成双稳态寄存器.</li><li>DRAM 1T1C: 1 MOSFET + 1 电容; 容量高但需周期刷新 (64ms 内必须读回写一次).</li><li>PLL 用作时钟倍频, ADC 把&quot;模拟信号&quot; 数化为 ADC 输出.</li></ul><p>→ 这一层给硬件上一个&quot;稳定态 + 离散数字&quot;契约; 上层第 3 层 RTL 不再关心电压.</p><h3 id="_2-3-第-3-层-数字逻辑-rtl-verilog" tabindex="-1">2.3 第 3 层: 数字逻辑 (RTL / Verilog) <a class="header-anchor" href="#_2-3-第-3-层-数字逻辑-rtl-verilog" aria-label="Permalink to &quot;2.3 第 3 层: 数字逻辑 (RTL / Verilog)&quot;">​</a></h3><p><strong>契约</strong>: 把布尔函数 (组合) 与时序逻辑 (状态) 组成可综合电路; 时钟无穷假设下, 输出由输入决定.</p><ul><li>RTL (Register-Transfer Level): Verilog / VHDL 描述数据在寄存器之间流动 + 触发时序.</li><li>自动综合 + 布局布线 (PD).</li><li>关键抽象: 时钟域同步 (CDC), 亚稳态 (metastability), 关键路径 (timing closure).</li><li>组合电路: 逻辑门, 多路选择, 算术单元 (一位加法基本是 28T 半加器 + 9T 全加).</li><li>时序电路: 触发器 + 状态机 + counter.</li></ul><h3 id="_2-4-第-4-层-微架构-microarch" tabindex="-1">2.4 第 4 层: 微架构 (microarch) <a class="header-anchor" href="#_2-4-第-4-层-微架构-microarch" aria-label="Permalink to &quot;2.4 第 4 层: 微架构 (microarch)&quot;">​</a></h3><p><strong>契约</strong>: 把 RTL 实现成&quot;对上一层 ISA 提供指令的时间抽象&quot; — 一条指令在多少周期做完、是否可乱序、是否可预测.</p><ul><li>流水线 (5 级 / 16 级), 超标量 + OoO (Tomasulo), 分支预测 (Tage / Perceptron).</li><li>Cache 层次 L1 / L2 / L3 / DRAM → 见 <a href="./../computer-arch/memory-hierarchy">第八部分 memory hierarchy</a>.</li><li>Memory consistency &amp; reorder buffer (ROB), memory ordering.</li><li>TLB + huge page + page walk.</li><li>GPU SM / warp scheduler; Tensor Core 矩阵乘张量核心.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Spectre (2018) 的本质</strong>: 微架构的 OoO + 分支预测打破了&quot;用户态 / 内核态&quot;在 ISA 上的契约 — 在 speculatively executed 失败路径上的 cache 副作用被攻击者读出 → 侧信道泄漏. 例子是&quot; 第 4 层的 speculative 行为泄漏给第 7 层的程序&quot;.</p></div><hr><h2 id="三、中层-第-5-7-层" tabindex="-1">三、中层: 第 5-7 层 <a class="header-anchor" href="#三、中层-第-5-7-层" aria-label="Permalink to &quot;三、中层: 第 5-7 层&quot;">​</a></h2><h3 id="_3-1-第-5-层-isa-instruction-set-architecture" tabindex="-1">3.1 第 5 层: ISA (Instruction Set Architecture) <a class="header-anchor" href="#_3-1-第-5-层-isa-instruction-set-architecture" aria-label="Permalink to &quot;3.1 第 5 层: ISA (Instruction Set Architecture)&quot;">​</a></h3><p><strong>契约</strong>: 一份&quot;机器指令 + 寄存器 + 寻址模式 + 系统态&quot;的精确规范, 上层编译器目标即它, 下层微架构实现即它.</p><ul><li><strong>CISC</strong>: x86-64 / zArch. 变长指令, 复杂寻址, 长历史兼容.</li><li><strong>RISC</strong>: ARM (v8/v9), RISC-V, MIPS. 固定 32 位指令, load-store 抽象, 解码简单.</li><li>子系统: 向量扩展 (AVX-512 / SVE2 / RISC-V V), AMX (Intel Advanced Matrix Extensions), Apple Silicon Matrix Coprocessor.</li></ul><p>→ 第 8 部分 <a href="./../computer-arch/isa-design">指令集架构</a> 详解.</p><h3 id="_3-2-第-6-层-操作系统内核" tabindex="-1">3.2 第 6 层: 操作系统内核 <a class="header-anchor" href="#_3-2-第-6-层-操作系统内核" aria-label="Permalink to &quot;3.2 第 6 层: 操作系统内核&quot;">​</a></h3><p><strong>契约</strong>: 通过系统调用接口, 对上层隐藏硬件细节: 进程调度、虚拟内存 / 页表、文件系统、套接字、设备驱动.</p><ul><li>Unix: 进程 fork/exec, 文件 = 字节流, 设备 = /dev 下 file-like, socket = file descriptor.</li><li>Linux: monolithic + module; CFS 调度, cgroup v2 隔离, eBPF 动态扩展.</li><li>Windows NT: 微内核思想实用化, micro-kernel-ish + Executive.</li></ul><p>→ 第二部分 <a href="./../os/">OS</a> 全部讲这一层.</p><h3 id="_3-3-第-7-层-系统调用-posix" tabindex="-1">3.3 第 7 层: 系统调用 POSIX <a class="header-anchor" href="#_3-3-第-7-层-系统调用-posix" aria-label="Permalink to &quot;3.3 第 7 层: 系统调用 POSIX&quot;">​</a></h3><p><strong>契约</strong>: 上层应用看到的标准 API: <code>read/write/open/close/fork/exec/mmap/epoll/...</code>.</p><ul><li>POSIX (IEEE 1003.1) 让软件跨 Unix 兼容.</li><li>Windows Win32 等价.</li><li>这一层一旦定下来, 70 年的 C 代码都能在 2024 Linux 跑 (<code>grep old codebase</code>).</li><li><strong>典型泄漏</strong>: <code>fork + exec</code> 在 fork 后 fd 复制仍占用 → 父子进程都需 <code>close</code>. Threads 不是&quot;轻量 fork&quot; → 用 <code>pthread_create</code> 而且内存共享 (信号 mask, thread-local, errno 要小心).</li></ul><hr><h2 id="四、上层-第-8-10-层" tabindex="-1">四、上层: 第 8-10 层 <a class="header-anchor" href="#四、上层-第-8-10-层" aria-label="Permalink to &quot;四、上层: 第 8-10 层&quot;">​</a></h2><h3 id="_4-1-第-8-层-高级语言运行时" tabindex="-1">4.1 第 8 层: 高级语言运行时 <a class="header-anchor" href="#_4-1-第-8-层-高级语言运行时" aria-label="Permalink to &quot;4.1 第 8 层: 高级语言运行时&quot;">​</a></h3><p><strong>契约</strong>: 提供更高级抽象 (GC / 闭包 / 模块 / 异步) 对编译后的字节码 / 解释后的 AST 解释运行, 调系统调用完成 IO.</p><ul><li><strong>JVM / HotSpot</strong>: 字节码 + JIT (tiered compilation 把热点方法机编本地 code).</li><li><strong>CPython</strong>: 解释 + 字节码; GIL (global interpreter lock) 限制纯 Python 多线程; PyPy JIT.</li><li><strong>V8 / JS 引擎</strong>: tiered JIT (Ignition + TurboFan + Maglev + Sparkplug).</li><li><strong>Go runtime</strong>: goroutine + GMP + runtime 调度 + channel, binary 自带.</li><li><strong>Erlang BEAM</strong>: actor 模型 + 极轻量进程 + 热升级.</li><li><strong>C/Rust</strong>: 无运行时 (Rust 用 minimal runtime), 编译到机器码直接跑.</li></ul><p>→ 第五部分编译原理的 <a href="./../compilers/codegen/jit">JIT</a> 与 _meta <a href="./../_meta/runtime-semantics">runtime-semantics</a> 详解各派不同.</p><h3 id="_4-2-第-9-层-应用与框架层" tabindex="-1">4.2 第 9 层: 应用与框架层 <a class="header-anchor" href="#_4-2-第-9-层-应用与框架层" aria-label="Permalink to &quot;4.2 第 9 层: 应用与框架层&quot;">​</a></h3><p><strong>契约</strong>: 业务语义 + 编程框架的库抽象 + DevOps 链路.</p><ul><li>Web: React / Vue / Spring / Gin / Django; BFF; 后端服务 (RPC / GraphQL).</li><li>数据库客户端: ORM (Hibernate / SQLAlchemy / GORM); 迁移工具 (Flyway).</li><li>分布式: Kafka / Pulsar; gRPC / Thrift; Etcd / ZooKeeper; K8s operator / Helm / Argo CD.</li><li>数据 / ML: Spark / Flink / Dask / Ray / Airflow; experiment tracking (MLflow / W&amp;B).</li></ul><p>→ 第七部分 <a href="./../system-design/">系统设计</a> 与第六部分 <a href="./../distributed/">分布式</a> 都在这一层操作.</p><h3 id="_4-3-第-10-层-ai-模型-agent" tabindex="-1">4.3 第 10 层: AI 模型 / Agent <a class="header-anchor" href="#_4-3-第-10-层-ai-模型-agent" aria-label="Permalink to &quot;4.3 第 10 层: AI 模型 / Agent&quot;">​</a></h3><p><strong>契约</strong>: 输入 prompt / multimodal content, 输出 tool call + text; 训练时还要有 reward 信号或对比信号.</p><ul><li>现状: 2024-2026 是&quot;模型即应用&quot; 范式年; LLM 不止续写, 还有 tool use (MCP), 长 context memory, multi-agent orchestration.</li><li>形态: 在线服务 (OpenAI / Anthropic API) vs 自托管开源模型 (LLaMA / Qwen / DeepSeek) vs 端侧模型 (Apple Intelligence / Phi-3) vs 嵌入式 (NPU on phone).</li><li>关键不变式破坏: 训练数据分布 ✗ 推理分布 (covariate shift) / 测试时思考预算 ≠ 训练分布 / 多模态对齐困难.</li></ul><p>→ 第十二部分 <a href="./../ai-ml/">AI/ML</a> 与未来可能的 RL/Agent 章节.</p><hr><h2 id="五、横向跨层的几个关键事实" tabindex="-1">五、横向跨层的几个关键事实 <a class="header-anchor" href="#五、横向跨层的几个关键事实" aria-label="Permalink to &quot;五、横向跨层的几个关键事实&quot;">​</a></h2><h3 id="_5-1-一条-虚拟-→-物理-一条-逻辑-→-概率-主干" tabindex="-1">5.1 一条&quot;虚拟 → 物理&quot; + 一条&quot;逻辑 → 概率&quot; 主干 <a class="header-anchor" href="#_5-1-一条-虚拟-→-物理-一条-逻辑-→-概率-主干" aria-label="Permalink to &quot;5.1 一条&quot;虚拟 → 物理&quot; + 一条&quot;逻辑 → 概率&quot; 主干&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10. 语义 / 行为        Agent 语义 / 训练目标</span></span>
<span class="line"><span>9.  应用 / 业务         组件 + 数据流</span></span>
<span class="line"><span>8.  运行时             类型 + 函数 + GC</span></span>
<span class="line"><span>7.  POSIX              fd / file / socket</span></span>
<span class="line"><span>6.  内核               进程 / 虚拟内存 / inode</span></span>
<span class="line"><span>5.  ISA                寄存器 + 指令</span></span>
<span class="line"><span>4.  microarch          ROB / cache / TLB / branch pred</span></span>
<span class="line"><span>3.  RTL                寄存器 + 组合逻辑</span></span>
<span class="line"><span>2.  模拟               SRAM / DRAM cell / PLL</span></span>
<span class="line"><span>1.  物理               MOSFET / 掺杂 / PN 结</span></span>
<span class="line"><span>─────────────────────────────────────────</span></span>
<span class="line"><span>对调 → 一条&quot;从概率到行为&quot;主干 (AI 层的来源)</span></span></code></pre></div><p>向下&quot;从可计算到物理可造&quot;, 向上&quot;从工程到语义可表达&quot;. 这个对称是抽象的根本.</p><h3 id="_5-2-每条层对调-走-1ms-都要多少层" tabindex="-1">5.2 每条层对调, 走 1ms 都要多少层? <a class="header-anchor" href="#_5-2-每条层对调-走-1ms-都要多少层" aria-label="Permalink to &quot;5.2 每条层对调, 走 1ms 都要多少层?&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你点按钮 (10 Layer)</span></span>
<span class="line"><span>  → React handler -&gt; 服务后端路由 (9)</span></span>
<span class="line"><span>    → Python 调 OS write (8→7)</span></span>
<span class="line"><span>      → kernel epoll (6)</span></span>
<span class="line"><span>        → NIC 驱动 (5→6 跨)</span></span>
<span class="line"><span>          → NIC 物理 PHY (4→3→2→1)</span></span>
<span class="line"><span>            → 光纤传输</span></span>
<span class="line"><span>              → 远端 反向</span></span>
<span class="line"><span>                → ...→ DB cache hit</span></span>
<span class="line"><span>                  → 返回</span></span>
<span class="line"><span>                    → 经历同样 10 层回你屏幕</span></span>
<span class="line"><span> total ~ 50ms 到 10s 视复杂度</span></span></code></pre></div><p>→ 这就是&quot;为什么优化 latency 要看哪一层泄漏&quot;. 跨 1ms 不是一层优化的事.</p><h3 id="_5-3-抽象的成本与边界" tabindex="-1">5.3 抽象的成本与边界 <a class="header-anchor" href="#_5-3-抽象的成本与边界" aria-label="Permalink to &quot;5.3 抽象的成本与边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th>抽象</th><th>提供的便利</th><th>限制 / 失效</th></tr></thead><tbody><tr><td>虚拟内存</td><td>独立地址空间</td><td>page fault / swap / NUMA</td></tr><tr><td>进程</td><td>隔离建执行单位</td><td>context switch / fork copy-on-write</td></tr><tr><td>文件</td><td>字节流 / 不可变语义</td><td>SSD trim 与 GC、fsync 协议</td></tr><tr><td>套接字</td><td>reliable TCP 上 byte stream</td><td>跨网 RTT / TCP 拥塞 / head-of-line</td></tr><tr><td>容器</td><td>进程级环境一致</td><td>内核共享 → Spectre / Meltdown 风险</td></tr><tr><td>VM</td><td>完整 OS 级隔离</td><td>hypervisor 损失</td></tr><tr><td>浏览器 DOM</td><td>HTML + JS DOM API</td><td>XSS / reflow layout thrashing</td></tr><tr><td>数据类型</td><td>静态保证</td><td>运行时 Cast / 不安全语言</td></tr><tr><td>GC</td><td>让你忘 free</td><td>STW / heap pressure</td></tr><tr><td>ML 模型</td><td>自然语言接口</td><td>&quot;幻觉&quot; / 训练分布外</td></tr></tbody></table><p>每条左侧给了便利, 它依赖右侧的实现细节往往在压力下泄漏.</p><hr><h2 id="六、抽象怎么-被打破-——5-个真实历史事件" tabindex="-1">六、抽象怎么&quot;被打破&quot;——5 个真实历史事件 <a class="header-anchor" href="#六、抽象怎么-被打破-——5-个真实历史事件" aria-label="Permalink to &quot;六、抽象怎么&quot;被打破&quot;——5 个真实历史事件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事件</th><th>年份</th><th>层级泄漏</th><th>关键人物 / 论文</th></tr></thead><tbody><tr><td><strong>Pentium FDIV bug</strong></td><td>1994</td><td>第 4 层 ALU 查表错误 → 第 5 层 ISA 契约错 (除法精度)</td><td>Intel 损失 4.75 亿美元召回</td></tr><tr><td><strong>Meltdown / Spectre</strong></td><td>2018</td><td>第 4 层 speculative exec 副作用 → 第 7 层 跨进程读 kernel</td><td>Google Project Zero, Graz Univ.</td></tr><tr><td><strong>Rowhammer</strong></td><td>2014</td><td>第 2 层 DRAM cell 电磁耦合 → 第 6 层 跨进程 priv 升 (Flip)</td><td>CMU + 等论文</td></tr><tr><td><strong>Redis 主从延迟</strong></td><td>2016 众</td><td>第 6 层 vm page cache 与 fork → 第 9 层 RTT 抖动</td><td>Latency 99 实践</td></tr><tr><td><strong>GPT-4 数算 7+7=14</strong></td><td>2023+</td><td>第 10 层统计模型对&quot;算术&quot;等离散变换推不上 → 上 audit fail</td><td>多家推理模型 + verifier 都在补</td></tr></tbody></table><p>每个都是&quot;下一层物理 / 微架构行为把上层契约撕掉一块&quot;; 一旦撕掉, 修法常常是要在<strong>多层</strong>同时打补丁.</p><hr><h2 id="七、抽象层级的工程用法" tabindex="-1">七、抽象层级的工程用法 <a class="header-anchor" href="#七、抽象层级的工程用法" aria-label="Permalink to &quot;七、抽象层级的工程用法&quot;">​</a></h2><h3 id="_7-1-调试定位-把症状挂到某层" tabindex="-1">7.1 调试定位: &quot;把症状挂到某层&quot; <a class="header-anchor" href="#_7-1-调试定位-把症状挂到某层" aria-label="Permalink to &quot;7.1 调试定位: &quot;把症状挂到某层&quot;&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>现象: 服务 P99 抖动</span></span>
<span class="line"><span>9 (业务): 流量突增 / 队列爆 → 容量问题</span></span>
<span class="line"><span>8 (运行时): GC pause / go runtime block</span></span>
<span class="line"><span>7 (POSIX): epoll 漏 wake / TCP ack 慢</span></span>
<span class="line"><span>6 (内核): 调度延迟 / softirq starvation</span></span>
<span class="line"><span>5 (ISA): - (上层几乎不报)</span></span>
<span class="line"><span>4 (microarch): branch mispred / cache miss</span></span>
<span class="line"><span>3 (RTL): (几乎无)</span></span>
<span class="line"><span>2 (模拟): (硬件故障)</span></span>
<span class="line"><span>1 (物理): bit flip</span></span></code></pre></div><p>→ <strong>能力定位</strong>: 一旦你能把现象对应到大概一层, 你就知道该看哪个工具 (perf / strace / py-spy / vtune / ipfc / sledf).</p><h3 id="_7-2-系统设计-新抽象必须问-泄漏怎么办" tabindex="-1">7.2 系统设计: &quot;新抽象必须问&#39;泄漏怎么办&#39;&quot; <a class="header-anchor" href="#_7-2-系统设计-新抽象必须问-泄漏怎么办" aria-label="Permalink to &quot;7.2 系统设计: &quot;新抽象必须问&#39;泄漏怎么办&#39;&quot;&quot;">​</a></h3><p>设计 cache / scheduler / scheduler / predictor 时, <strong>先回答</strong>:</p><ul><li>&quot;失败时契约怎么退化?&quot;</li><li>&quot;性能泄漏到什么粒度?&quot;</li><li>&quot;并发 / 故障模型下不变式是什么?&quot;</li><li>&quot;依赖下层什么不变式? 下层失败呢?&quot;</li></ul><p>→ 见 <a href="./../_meta/hardware-shapes-software">第十三部分 _meta/brhardware-shapes-software</a> 与 <a href="./../os/sched/">第八部分 / OS 第 2 章</a>.</p><h3 id="_7-3-学习路径-沿层上下走" tabindex="-1">7.3 学习路径: &quot;沿层上下走&quot; <a class="header-anchor" href="#_7-3-学习路径-沿层上下走" aria-label="Permalink to &quot;7.3 学习路径: &quot;沿层上下走&quot;&quot;">​</a></h3><ul><li><strong>从程序员角度看</strong>, 学完高级语言 (8) 应该往上 ((9) 框架与 (10) AI 应用) 与往下 (指 7 POSIX 与 6 内核与 5 ISA) 各推一些.</li><li><strong>从硬件工程师角度看</strong>, 学完数字逻辑 (3) 应该往物理 (1-2) 与微型架构 (4) 与 ISA (5) 与内核 (6) 推.</li><li><strong>从 AI 工程师角度看</strong>, 应该至少熟悉 (10) 与 (9) + (8) + (5) (手算 attention FLOPs 都要 ISA 层系统) + (4) (Tensor Core / SM).</li></ul><hr><h2 id="八、与第零部分-各部分的接口" tabindex="-1">八、与第零部分 + 各部分的接口 <a class="header-anchor" href="#八、与第零部分-各部分的接口" aria-label="Permalink to &quot;八、与第零部分 + 各部分的接口&quot;">​</a></h2><ul><li>抽象 ↑层(10-9) 主线依靠第十二部分 AI/ML 与第七部分系统设计.</li><li>抽象 ↓层(1-4) 主线依靠第八部分组成原理.</li><li>第 5 ISA 直接对应第八部分 <a href="./../computer-arch/isa-design">isa-design</a>.</li><li>第 6 内核对应第二部分 <a href="./../os/">OS</a>.</li><li>第 7-8 之间——语言运行时 vs 系统调用——与第五部分 <a href="./../compilers/">compiler</a> + <a href="./../_meta/runtime-semantics">_meta runtime-semantics</a> 直接相关.</li><li>第 4 层泄漏洞的 <a href="./../crypto/sidechannel">crypto/sidechannel</a> 讲 Spectre/Meltdown 的密码学攻击面.</li><li>数学 (第零部分) 跨层使用: 第零部分线代对应 (4) 微架构张量核心; 概率对应 (10) AI 模型; 微积分/优化对应 (10).</li></ul><hr><h2 id="九、结束-速查表" tabindex="-1">九、结束 + 速查表 <a class="header-anchor" href="#九、结束-速查表" aria-label="Permalink to &quot;九、结束 + 速查表&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>一页快速唤回:</p><ul><li><strong>十层金字塔</strong>: 物理→模拟→RTL→microarch→ISA→kernel→POSIX→运行时→应用→AI.</li><li><strong>契约</strong>: 每层给上层一组语法 + 语义 + 不变式.</li><li><strong>泄漏是法则</strong>: 性能 / 正确性 / 资源 / 延迟 / 粒度 / 失败模型 — 6 种典型泄漏.</li><li><strong>历史教训</strong>: Pentium FDIV, Meltdown/Spectre, Rowhammer, Cloud futex, LLM 算错.</li><li><strong>调试法</strong>: 把症状先挑到恰当层, 再选工具.</li><li><strong>设计法</strong>: 抽象新发明, 预先回答&quot;4 个问题&quot; (回退/性能/并发/失败).</li><li><strong>学习法</strong>: 沿层上下交替推 — 程序员往上下各, 硬件工往上下各, AI 工按需.</li></ul></div><hr><p>下一篇: <a href="./mainframe-xpu">3. 形态演进: 大型机 → PC → 单片机/ARM → 云 → Web → AI → XPU</a>.</p>`,95)])])}const u=s(l,[["render",i]]);export{d as __pageData,u as default};
